BEGIN;
CREATE TABLE public.profiles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', skills text NOT NULL DEFAULT '', experience numeric NOT NULL DEFAULT 0 CHECK(experience>=0), min_salary numeric NOT NULL DEFAULT 0 CHECK(min_salary>=0), currency text NOT NULL DEFAULT 'INR', workplace text NOT NULL DEFAULT 'any', job_type text NOT NULL DEFAULT '', max_posting_age integer NOT NULL DEFAULT 7 CHECK(max_posting_age BETWEEN 1 AND 365), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.profiles FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.profiles TO authenticated;
CREATE POLICY owner_only ON public.profiles FOR ALL TO authenticated USING ((select auth.uid()) = user_id) WITH CHECK ((select auth.uid()) = user_id);
CREATE TABLE public.resumes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, UNIQUE(user_id,id), source_text text NOT NULL CHECK(length(source_text) BETWEEN 20 AND 30000), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.resumes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.resumes FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.resumes TO authenticated;
CREATE POLICY owner_only ON public.resumes FOR ALL TO authenticated USING ((select auth.uid()) = user_id) WITH CHECK ((select auth.uid()) = user_id);
CREATE TABLE public.claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, UNIQUE(user_id,id), resume_id uuid NOT NULL, section text NOT NULL, exact_text text NOT NULL, source_span jsonb NOT NULL, FOREIGN KEY(user_id,resume_id) REFERENCES public.resumes(user_id,id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.claims ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.claims FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.claims TO authenticated;
CREATE POLICY owner_only ON public.claims FOR ALL TO authenticated USING ((select auth.uid()) = user_id) WITH CHECK ((select auth.uid()) = user_id);
CREATE TABLE public.evidence_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, UNIQUE(user_id,id), claim_id uuid NOT NULL, url text NOT NULL, FOREIGN KEY(user_id,claim_id) REFERENCES public.claims(user_id,id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.evidence_links ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.evidence_links FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.evidence_links TO authenticated;
CREATE POLICY owner_only ON public.evidence_links FOR ALL TO authenticated USING ((select auth.uid()) = user_id) WITH CHECK ((select auth.uid()) = user_id);
CREATE TABLE public.job_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, UNIQUE(user_id,id), ats text NOT NULL, board_slug text NOT NULL, active boolean NOT NULL DEFAULT true, UNIQUE(user_id,ats,board_slug), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.job_sources ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.job_sources FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.job_sources TO authenticated;
CREATE POLICY owner_only ON public.job_sources FOR ALL TO authenticated USING ((select auth.uid()) = user_id) WITH CHECK ((select auth.uid()) = user_id);
CREATE TABLE public.user_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, UNIQUE(user_id,id), source_id uuid NOT NULL, external_id text NOT NULL, snapshot jsonb NOT NULL, published_at timestamptz, updated_at timestamptz, first_seen_at timestamptz NOT NULL DEFAULT now(), last_checked_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(user_id,source_id) REFERENCES public.job_sources(user_id,id) ON DELETE CASCADE, UNIQUE(user_id,source_id,external_id), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.user_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.user_jobs FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.user_jobs TO authenticated;
CREATE POLICY owner_only ON public.user_jobs FOR ALL TO authenticated USING ((select auth.uid()) = user_id) WITH CHECK ((select auth.uid()) = user_id);
CREATE TABLE public.applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, UNIQUE(user_id,id), job_id uuid NOT NULL, resume_id uuid, packet jsonb NOT NULL DEFAULT '{}'::jsonb, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','held','simulated','sending','sent','uncertain','failed','skipped')), reason text NOT NULL DEFAULT '', FOREIGN KEY(user_id,job_id) REFERENCES public.user_jobs(user_id,id), FOREIGN KEY(user_id,resume_id) REFERENCES public.resumes(user_id,id), UNIQUE(user_id,job_id), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.applications FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.applications TO authenticated;
CREATE POLICY owner_only ON public.applications FOR ALL TO authenticated USING ((select auth.uid()) = user_id) WITH CHECK ((select auth.uid()) = user_id);
CREATE TABLE public.application_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, UNIQUE(user_id,id), application_id uuid NOT NULL, event text NOT NULL, FOREIGN KEY(user_id,application_id) REFERENCES public.applications(user_id,id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.application_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.application_events FROM anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.application_events TO authenticated;
CREATE POLICY owner_only ON public.application_events FOR ALL TO authenticated USING ((select auth.uid()) = user_id) WITH CHECK ((select auth.uid()) = user_id);
COMMIT;
